}

func (c *clientCache) Store(k string, v []sanaei.ClientRecord) {
	if c.m == nil {
		c.m = map[string][]sanaei.ClientRecord{}
	}

	c.m[k] = v
}
func (c *clientCache) Load(k string) (any, bool) { v, ok := c.m[k]; return v, ok }

func ProviderID(id int) string { return strconv.Itoa(id) }
func waitDelay(attempt int) time.Duration {
	// Provider polling budget: 2s, 4s, 8s, then at most once every 15s.
	// This keeps activation responsive without hammering the provider API.

if attempt < 1 {
	attempt = 1
}
d := 2 * time.Second
for i := 1; i < attempt && d < 15*time.Second; i++ {
	d *= 2
}
if d > 15*time.Second {

		d = 15 * time.Second
	}
	return d
}

)

var ErrResourceNotReady = errors.New("provider resource not ready")

type ServerWaiter struct {
	Provider providers.ComputeDriver
	Timeout  time.Duration
}

func (w ServerWaiter) Wait(ctx context.Context, providerID string) (ResourceInfo, error) {
	if w.Provider == nil || providerID == "" {
		return ResourceInfo{}, ErrRuntimeConfig
	}
	timeout := w.Timeout
	if timeout <= 0 {
		timeout = 3 * time.Minute

}
deadline := time.NewTimer(timeout)
defer deadline.Stop()
attempt := 0
for {
	attempt++
	x, err := w.Provider.GetServer(ctx, providerID)
	if err == nil && x.Ready && x.PrimaryIPv4 != "" {

	return ResourceInfo{ProviderID: x.ID, Host: x.PrimaryIPv4}, nil
}
if err != nil && !providers.IsClass(err, providers.ErrorNotFound) && !providers.IsRetryable(err) {
	return ResourceInfo{}, err
}
select {
case <-ctx.Done():
	return ResourceInfo{}, ctx.Err()

		case <-deadline.C:
			return ResourceInfo{}, ErrResourceNotReady
		case <-time.After(waitDelay(attempt)):
		}
	}
}

